const FALLBACK_PALETTES = [
  {
    gradient: "linear-gradient(135deg, #0f4c81 0%, #0284c7 58%, #38bdf8 100%)",
    accentHex: "#0284c7",
  },
  {
    gradient: "linear-gradient(135deg, #065f46 0%, #0d9488 58%, #2dd4bf 100%)",
    accentHex: "#0d9488",
  },
  {
    gradient: "linear-gradient(135deg, #1e3a8a 0%, #3b82f6 58%, #60a5fa 100%)",
    accentHex: "#2563eb",
  },
  {
    gradient: "linear-gradient(135deg, #7c2d12 0%, #c2410c 58%, #fb923c 100%)",
    accentHex: "#c2410c",
  },
  {
    gradient: "linear-gradient(135deg, #1f2937 0%, #334155 58%, #64748b 100%)",
    accentHex: "#334155",
  },
];

function hashSeed(text: string): number {
  let h = 0;
  for (let i = 0; i < text.length; i++) {
    h = (h * 31 + text.charCodeAt(i)) >>> 0;
  }
  return h;
}

export function resolveSiteBrandAppearance(params: {
  slug?: string;
  domain?: string;
  name: string;
}): {
  brandKey: string;
  gradient: string;
  accentHex: string;
  spec: SiteBrandSpec | null;
} {
  const key = resolveBrandKey(params.slug, params.domain);
  const spec = BRAND_SPECS[key] ?? null;
  if (spec) {
    return {
      brandKey: spec.key,
      gradient: spec.gradient,
      accentHex: spec.accentHex,
      spec,
    };
  }
  const palette =
    FALLBACK_PALETTES[
      hashSeed(`${params.domain || ""}:${params.name}`) %
        FALLBACK_PALETTES.length
    ]!;
  return {
    brandKey: "custom",
    gradient: palette.gradient,
    accentHex: palette.accentHex,
    spec: null,
  };
}

export function SiteBrandMark({
  slug,
  domain,
  name,
  size = "md",
  className = "",
}: {
  slug?: string;
  domain?: string;
  name: string;
  size?: "sm" | "md" | "lg";
  className?: string;
}) {
  const { brandKey, gradient, spec } = resolveSiteBrandAppearance({
    slug,
    domain,
    name,
  });

  const boxClass =
    size === "sm"
      ? "w-7 h-7 rounded-lg"
      : size === "lg"
        ? "w-11 h-11 rounded-xl"
        : "w-10 h-10 rounded-xl";
  const iconClass =
    size === "sm"
      ? "w-4 h-4"
      : size === "lg"
        ? "w-6 h-6"
        : "w-5 h-5";

  const monogram =
    name
      .replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, "")
      .slice(0, 2)
      .toUpperCase() || "OK";

  return (
    <span
      data-brand-mark={brandKey}
      style={{
        backgroundImage: gradient,
        boxShadow:
          "inset 0 1px 0 rgba(255,255,255,0.26), 0 4px 10px -3px rgba(15,23,42,0.24)",
      }}
      className={`${boxClass} text-white relative inline-flex items-center justify-center shrink-0 overflow-hidden select-none transition-transform duration-200 group-hover:scale-[1.04] ${className}`}
    >
      {spec ? (
        spec.renderGlyph(iconClass)
      ) : (
        <span className="font-mono text-[11px] font-bold tracking-tight text-white">
          {monogram}
        </span>
      )}
    </span>
  );
}

/** 整张卡片共用品牌色，水印只作背景，不截获点击。 */
export function BrandCardBackdrop({brand}: {brand: ReturnType<typeof resolveSiteBrandAppearance>}) {
  return <span aria-hidden="true" className="brand-card-surface" style={{backgroundImage: brand.gradient}}>
    {brand.spec?.renderGlyph("brand-watermark")}
  </span>;
}
